package engine

// The Gregorian calendar data of Intl.DateTimeFormat (intl_date_tables.go,
// generated by internal/gen/cldr): each data locale's record decodes on its
// first use into an intlDateData whose strings are slices of the string
// pool, and its pattern generator (intl_date_pattern.go) builds on the
// first pattern it is asked for.

import (
	"strings"
	"sync"
	"sync/atomic"
	"unsafe"
)

// intlDateData is a data locale's calendar data, as ICU's
// DateFormatSymbols and DateTimePatternGenerator hold it.
type intlDateData struct {
	// months and days by width: format abbreviated, wide, narrow, then
	// stand-alone abbreviated, wide, narrow; days from Sunday.
	months [6][12]string
	days   [6][7]string
	// eras (BC, AD), am/pm and the day periods (ICU's DayPeriod order,
	// midnight to night2, "" where the locale has none), by width:
	// abbreviated, wide, narrow.
	eras    [3][2]string
	ampm    [3][2]string
	periods [3][10]string
	// periodRules is ICU's DayPeriodRules of the locale: '1' when it has
	// midnight, '1' when it has noon, then the period of each hour as a
	// digit from '0' (10 am, 11 pm).
	periodRules string
	// timeFormats and dateFormats are the styles' patterns, full to short;
	// glue joins a date and a time ({1} the date, {0} the time) for each date
	// style, atTime too (ICU's %atTime, the standard glue when the locale
	// has none).
	timeFormats, dateFormats [4]string
	glue, atTime             [4]string
	// appendItems and fieldNames are by DateTimePatternGenerator field.
	appendItems, fieldNames [16]string
	// decimal is the decimal separator of the latn digits; decimals lists
	// those of the numbering systems where they differ ("arab:٫;").
	decimal, decimals string
	// avail is availableFormats: skeleton, pattern, ... in ICU's order.
	avail []string
	// intervalFallback is "{0} – {1}" and the like; intervals are the
	// intervalFormats by skeleton.
	intervalFallback string
	intervals        []intlIntervalItem

	gen     [2]intlPatternMap // with and without the style patterns (intl_date_pattern.go)
	genOnce [2]sync.Once
	// patterns caches getBestPattern (intlPatternKey → string), compiled
	// the compiled patterns (pattern → []intlDateItem) and ranges the
	// interval formatters (intlRangeKey → *intlDateRange), within
	// intlDateCacheBudget: the options of a script choose the keys. itv is
	// the DateIntervalInfo the interval formatters share.
	patterns, compiled, ranges sync.Map
	itv                        *intlItvInfo
	itvOnce                    sync.Once
}

// intlDateCacheBudget is about the bytes the caches of patterns, compiled
// patterns and interval formatters hold together, over every data index:
// they are process-wide and charged to no realm, so the regional locales'
// data indexes share the budget rather than multiply it. Past it, what a
// formatter makes is its own and charged to its realm.
const intlDateCacheBudget = 16 << 20

// intlDateCacheEntry estimates what a cache entry takes besides its key's
// and value's data: the map's slot, the entry and the boxed key and value.
const intlDateCacheEntry = 128

// intlDateCacheUsed counts the bytes of intlDateCacheBudget taken.
var intlDateCacheUsed atomic.Int64

// intlCacheTake takes n bytes of intlDateCacheBudget for an entry, false
// when they pass it. A spent budget is only read, so the counter stops
// there.
func intlCacheTake(n int) bool {
	return intlDateCacheUsed.Load() < intlDateCacheBudget && intlDateCacheUsed.Add(int64(n+intlDateCacheEntry)) <= intlDateCacheBudget
}

// intlCacheRefund gives back what intlCacheTake took for an entry another
// goroutine stored first, which missed the same key at the same time.
func intlCacheRefund(n int) {
	intlDateCacheUsed.Add(-int64(n + intlDateCacheEntry))
}

// compile returns a pattern's items, compiled once per locale; once the
// caches' budget is spent, they are the formatter's own and charged to r
// (nil for no charge).
func (d *intlDateData) compile(r *Realm, p string) []intlDateItem {
	if v, ok := d.compiled.Load(p); ok {
		return v.([]intlDateItem)
	}
	items := intlCompilePattern(p)
	n := len(items) * int(unsafe.Sizeof(intlDateItem{}))
	for _, it := range items {
		n += len(it.lit)
	}
	if intlCacheTake(len(p) + n) {
		if v, loaded := d.compiled.LoadOrStore(p, items); loaded {
			intlCacheRefund(len(p) + n)
			items = v.([]intlDateItem)
		}
	} else if r != nil {
		r.charge(n)
	}
	return items
}

// intlIntervalItem is an intervalFormatItem: the patterns of a skeleton by
// greatest difference (a pattern letter).
type intlIntervalItem struct {
	skeleton string
	diffs    []byte
	patterns []string
}

var (
	intlDateOnce   [intlDataIndexCount]sync.Once
	intlDateTables [intlDataIndexCount]*intlDateData
)

// intlDate returns the calendar data of a data index, decoding it on first
// use. A regional locale whose calendar data is its parent's (en-GU,
// fr-GF: an empty delta) shares its parent's, caches included.
func intlDate(i int) *intlDateData {
	intlDateOnce[i].Do(func() {
		if k := i - intlDataLocaleCount; k >= 0 && intlDateSubRecords[k] == "" {
			intlDateTables[i] = intlDate(intlSubLocaleList()[k].parent)
			return
		}
		intlDateTables[i] = intlDecodeDate(intlDateTable.record(i))
	})
	return intlDateTables[i]
}

// intlDateReader reads a record of intlDateRecords.
type intlDateReader struct{ rec string }

func (r *intlDateReader) num() int {
	v, shift := 0, 0
	for {
		c := r.rec[0]
		r.rec = r.rec[1:]
		v |= int(c&0x7f) << shift
		if c < 0x80 {
			return v
		}
		shift += 7
	}
}

// str reads a reference into intlDateStrings.
func (r *intlDateReader) str() string {
	s := intlDateStrings[r.num():]
	return s[:strings.IndexByte(s, 0)]
}

// list reads a list of names into dst.
func (r *intlDateReader) list(dst []string) {
	s := r.str()
	for i := range dst {
		end := strings.IndexByte(s, 1)
		if end < 0 {
			end = len(s)
		}
		dst[i] = s[:end]
		s = s[min(end+1, len(s)):]
	}
}

func intlDecodeDate(rec string) *intlDateData {
	r := &intlDateReader{rec}
	d := &intlDateData{}
	for i := range d.months {
		r.list(d.months[i][:])
	}
	for i := range d.days {
		r.list(d.days[i][:])
	}
	for i := range d.eras {
		r.list(d.eras[i][:])
	}
	for i := range 3 {
		r.list(d.ampm[i][:])
		r.list(d.periods[i][:])
	}
	d.periodRules = r.str()
	for i := range d.timeFormats {
		d.timeFormats[i] = r.str()
	}
	for i := range d.dateFormats {
		d.dateFormats[i] = r.str()
	}
	for i := range d.glue {
		d.glue[i] = r.str()
	}
	for i := range d.atTime {
		d.atTime[i] = r.str()
	}
	r.list(d.appendItems[:])
	r.list(d.fieldNames[:])
	d.decimal = r.str()
	d.decimals = r.str()
	n := r.num()
	d.avail = make([]string, 2*n)
	for i := range d.avail {
		d.avail[i] = r.str()
	}
	d.intervalFallback = r.str()
	d.intervals = make([]intlIntervalItem, r.num())
	for i := range d.intervals {
		it := &d.intervals[i]
		it.skeleton = r.str()
		k := r.num()
		it.diffs = make([]byte, k)
		it.patterns = make([]string, k)
		for j := range k {
			it.diffs[j] = byte(r.num())
			it.patterns[j] = r.str()
		}
	}
	return d
}

// decimalOf returns the decimal separator of a numbering system.
func (d *intlDateData) decimalOf(nu string) string {
	if v, ok := intlRecord(d.decimals, nu); ok {
		return v
	}
	return d.decimal
}

// periodOf returns ICU's DayPeriod of an hour, and whether the rules have
// midnight and noon.
func (d *intlDateData) periodOf(hour int) int { return int(d.periodRules[2+hour] - '0') }
func (d *intlDateData) hasMidnight() bool     { return d.periodRules[0] == '1' }
func (d *intlDateData) hasNoon() bool         { return d.periodRules[1] == '1' }
